import{_ as e,o as n,c as r,a4 as s}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20250830082042717.CxczrO4-.png",i="/assets/image-20250830081833547.C7ZneCOP.png",o="/assets/image-20250830082128259.CbuNYO01.png",l="/assets/image-20250830082236922.Di3_JoaU.png",m="/assets/image-20250830095111424.Cokdm9oF.png",p="/assets/image-20250830095159281.qSpCT2ld.png",c="/assets/image-20250830095229296.D_X3WG88.png",h="/assets/image-20250830082802725.ByA-rSu7.png",d="/assets/image-20250822223258675.CJHnmYEl.png",g="/assets/wanshaoweixin.DWzIcicW.jpg",w=JSON.parse('{"title":"2025年 华为鸿蒙创新赛比赛流程 全攻略","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/2025年 华为鸿蒙创新赛比赛流程 全攻略/2025年 华为鸿蒙创新赛比赛流程 全攻略.md","filePath":"鸿蒙开发技巧/2025年 华为鸿蒙创新赛比赛流程 全攻略/2025年 华为鸿蒙创新赛比赛流程 全攻略.md","lastUpdated":1757677612000,"__rawMarkdown":"#  2025年 华为鸿蒙创新赛比赛流程 全攻略\\n\\n各位开发者朋友们，大家好！\\n\\n华为鸿蒙创新赛又来了！这可是每年开发者圈子里的重头戏，不仅有丰厚的奖金，更是展示自己技术实力、获得行业认可的绝佳机会。今天就来给大家详细拆解一下2025年的参赛流程，让你轻松上手，避免踩坑！\\n\\n> https://developer.huawei.com/consumer/cn/activity/digixActivity/digixcmsdetail/101750143863263087\\n\\n![image-20250830082042717](assets/image-20250830082042717.png)\\n\\n##  参赛流程总览\\n\\n为了让大家对整个参赛流程有个清晰的认识，我先画个流程图给大家看看：\\n\\n![image-20250830081833547](assets/image-20250830081833547.png)\\n\\n通过这个流程图，相信大家对整个参赛过程已经有了直观的了解。接下来，我们逐步详细解析每个环节：\\n\\n##  第一步：报名注册\\n\\n首先当然是要报名啦，普通开发者和企业都可以报名参加！这一步相对简单，但也有几个注意事项：\\n\\n✅ **时间把控**：关注官方公布的报名截止时间，千万别错过\\n✅ **资料准备**：准备好个人或团队的基本信息\\n✅ **赛道选择**：根据自己的技术栈和兴趣选择合适的赛道\\n\\n![image-20250830082128259](assets/image-20250830082128259.png)\\n\\n##  第二步：开发HarmonyOS 5应用并发布上架\\n\\n这是整个流程中最核心的部分，也是最考验技术功底的环节，简单总结就是有创意、有人文关怀的作品更好，同时需要体现鸿蒙新特性。另外，需要注意的是，**先基于HarmonyOS5开发可以上架的作品，后面再接入6新特性 邀请测试即可。**\\n\\n![image-20250830082236922](assets/image-20250830082236922.png)\\n\\n\\n\\n##  第三步：应用上架策略\\n\\n这里有个重要的分叉路口，需要根据你的应用类型选择不同的策略：\\n\\n###  联网应用路线\\n如果你的作品是要连接外网，那么就需要备案+软著：\\n\\n1. 备案需要购买服务器\\n2. 软著-正常流程2个月，现在时间是，2025年8月30日，那肯定来不及了。但是可以**走易版权流程**\\n\\n###  单机应用路线\\n- **无需备案**：流程相对简化\\n- **无需软著**：降低了准备门槛\\n- **快速上线**：审核周期较短\\n\\n**如果时间紧张，可以考虑先做单机版本快速上线，后续再迭代联网功能。**\\n\\n## 第四步：应用商店上架\\n\\n这个是需要提交作品发布上架到鸿蒙应用商店的。具体流程可以详细沟通。\\n\\n![image-20250830095111424](assets/image-20250830095111424.png)\\n\\n\\n\\n## 第五步：接入鸿蒙6新特性\\n\\n当你的作品成功上架后，恭喜你已经实现90%的功能了，接下来你需要使用DevEco 6版本的开发工具来接入鸿蒙6的新特性，然后继续迭代一些功能即可。\\n\\n具体接入的新特性有哪些，可以查看这个：\\n\\n> https://developer.huawei.com/consumer/cn/doc/harmonyos-releases/os-new-feature-600\\n\\n![image-20250830095159281](assets/image-20250830095159281.png)\\n\\n##  第六步：申请白名单测试\\n\\n这一步需要联系华为技术人员，提供你的资料给他们，他们为你开通白名单，你才可以提交 邀请测试，这一步也是需要时间的，所以请提前准备好。\\n\\n## 第七步：提交邀请测试\\n\\n当对方通知你白名单已经开通，你就可以在agc平台上提交邀请测试了。\\n\\n![image-20250830095229296](assets/image-20250830095229296.png)\\n\\n##  第八步：编写展示材料\\n\\n测试通过后，需要准备最终的展示材料：\\n\\n![image-20250830082802725](assets/image-20250830082802725.png)\\n\\n##  第九步：最终提交与评比\\n\\n最后的冲刺阶段：\\n\\n- **材料检查**：确保所有材料都准备齐全\\n- **格式规范**：按照要求的格式提交\\n- **截止时间**：在截止时间前完成提交\\n- **心态调整**：保持良好心态，等待结果\\n\\n\\n\\n## 写在最后\\n\\n华为鸿蒙创新赛不仅是一场技术竞赛，更是开发者成长和展示的舞台。无论最终是否获奖，参与的过程本身就是宝贵的学习和成长机会。\\n\\n希望这份攻略能帮助到正在准备参赛的你！记住，技术是基础，创意是灵魂，坚持是关键！\\n\\n---\\n\\n如果你觉得这份攻略对你有帮助，欢迎关注我们的技术分享平台，获取更多开发干货和行业资讯。也可以添加我的微信，一起交流鸿蒙开发技术，共同进步！\\n\\n让我们一起在鸿蒙生态的浪潮中，书写属于开发者的精彩篇章！🚀\\n\\n## 以往文章\\n\\n\\n\\n- [可可图片编辑 HarmonyOS 上架应用分享](https://mp.weixin.qq.com/s?__biz=MzI0NjY1MDY3Mg==&mid=2247489342&idx=1&sn=15f4872e080ee3f86efdc32d6edfd979&chksm=e813ff241c45844ae10e1fb352499b7253ae91ad932db71f17e86fa2251bb17251d5d840d1ab&scene=126&sessionid=1756092287&subscene=91&clicktime=1756092289&enterid=1756092289#rd)\\n- [可可图片编辑 HarmonyOS（2） 选择图片和保存到图库](https://mp.weixin.qq.com/s/dacDD763JhrLkIS1V8rrdg)\\n- [懂你的HarmonyOS知识库更新了，已经来到10970个文档了](https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A)\\n- [AI编程神器！Trae+Claude4.0 简单配置 让 HarmonyOS 开发效率飙升](https://mp.weixin.qq.com/s/AsieJTX8RkixgaKyDrzddg)\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n![image-20250822223258675](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![wanshaoweixin](assets/wanshaoweixin.jpg)"}'),_={name:"鸿蒙开发技巧/2025年 华为鸿蒙创新赛比赛流程 全攻略/2025年 华为鸿蒙创新赛比赛流程 全攻略.md"};function u(b,a,f,q,x,k){return n(),r("div",null,[...a[0]||(a[0]=[s("",57)])])}const S=e(_,[["render",u]]);export{w as __pageData,S as default};
